// All backend calls of the Suppliers page. Docs: ../backend/doc/week1/supplier.txt
import api from "../../services/api";
import { toMoneyNumber } from "../../utils/money";

// Only the documented fields. `code` is generated by the server and never sent.
// email is added by createSupplier / updateSupplier (the rule differs, see below).
function toSupplierBody(form) {
  return {
    name: form.name.trim(),
    // Text fields: "" (not undefined) when emptied, so PATCH clears the old value.
    contactPerson: form.contactPerson.trim(),
    phone: form.phone.trim(),
    taxNumber: form.taxNumber.trim(),
    // Money: sent as a number (an empty field = 0).
    openingBalance: toMoneyNumber(form.openingBalance),
  };
}

export async function getSuppliers() {
  const response = await api.get("/supplier");
  return response.data.data;
}

// The backend checks the email format, so "" is rejected: on create an empty email is left out.
export async function createSupplier(form) {
  const body = toSupplierBody(form);
  const email = form.email.trim();
  if (email) body.email = email;

  const response = await api.post("/supplier", body);
  return response.data.data;
}

// On edit an emptied email is sent as null, which clears it.
export async function updateSupplier(id, form) {
  const body = { ...toSupplierBody(form), email: form.email.trim() || null };
  const response = await api.patch(`/supplier/${id}`, body);
  return response.data.data;
}

export async function deleteSupplier(id) {
  await api.delete(`/supplier/${id}`);
}
